/// <summary>
///     The <c>KCS_KBVBuildingProjectTable</c> class is the extension of table <c>common</c>
/// </summary>
public class KCS_KBVBuildingProjectTable extends common
{
}

Method.Source:
/// <summary>
///    AVA <c>setKCS_KBVBuildingProjectIDNumberSeq</c> method.
/// </summary>
public void setKCS_KBVBuildingProjectIDNumberSeq()
{
    NumberSeq   locNumberSeq;

    if(this.KCS_KBVBuildingProjectID == '')
    {
        locNumberSeq = NumberSeq::newGetNum(AVANumberSeqModuleBP::numRefKCS_KBVBuildingProjectID());

        this.KCS_KBVBuildingProjectID   = locNumberSeq.num();
    }
}

/// <summary>
///    AVA <c>initValue</c> method.
/// </summary>
public void initValue()
{
    CompanyInfo locCompanyInfo;

    locCompanyInfo  = CompanyInfo::find();

    super();

    this.KCS_KBVStatus              = KCS_KBVStatus::Project;
    this.KCS_KBVCreatedDate         = AVAKBVBuildingProjectHelper::getToday();
    this.KCS_KBVCreatedInDataAreaID = locCompanyInfo.DataArea; //CurExt();
    if(!this.KCS_KBVCreatedBy)
    {
        this.KCS_KBVCreatedBy       = HcmWorkerLookup::currentWorker();
    }
    this.AddressCountryRegionId     = locCompanyInfo.invoiceAddress().CountryRegionId;
}

/// <summary>
///    Finds the specified record in the <c>KCS_KBVBuildingProjectTable</c> table.
/// </summary>
/// <param name="_recordId">
///    The record ID of the <c>KCS_KBVBuildingProjectTable</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>KCS_KBVBuildingProjectTable</c> table; otherwise, an empty record.
/// </returns>
public static KCS_KBVBuildingProjectTable find( KCS_KBVBuildingProjectID    _recordId,
                                                boolean                     _forUpdate = false)
{
    KCS_KBVBuildingProjectTable record;

    if (_recordId)
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        index hint KCS_KBVBuildingProjectIDIdx
        where   record.KCS_KBVBuildingProjectID == _recordId;
    }

    return record;
}

