/// <summary>
///    AVA <c>insert</c> method.
/// </summary>
public void insert()
{
    this.setSalesDistrict();
    super();
    KCS_KBVBuildingProjectMemo::insertFromBuildingProject(this.KCS_KBVBuildingProjectID);
    KCS_KBVSearchTable::setFromCommonField(this.KCS_KBVBuildingProjectID,this,fieldNum(KCS_KBVBuildingProjectTable,KCS_KBVSubject));

}

/// <summary>
///    AVA <c>setSalesDistrict</c> method.
/// </summary>
/// <param name="_addressCountryRegionId">
///    <c>AddressCountryRegionId</c> as type
/// </param>
/// <param name="_addressZipCodeId">
///    <c>AddressZipCodeId</c> as type
/// </param>
public void setSalesDistrict(   AddressCountryRegionId  _addressCountryRegionId = '',
                                AddressZipCodeId        _addressZipCodeId       = '')
{
    KCS_KBVParameters           loc_KCS_KBVParameters;

    AddressZipCodeId            zipCode;
    AddressCountryRegionId      country;
    DataAreaId                  dataAreaId;

    loc_KCS_KBVParameters   = KCS_KBVParameters::find();
    dataAreaId              = loc_KCS_KBVParameters.KCS_DataAreaName;

    if (_addressCountryRegionId && _addressZipCodeId)
    {
        country = _addressCountryRegionId;
        zipCode = _addressZipCodeId;
    }
    else
    {
        country = this.AddressCountryRegionId;
        zipCode = this.AddressZipCodeId;
    }

    this.smmSalesDistrictId = AVAKBVHelperClass::ZipCode2SalesDistrict(  zipcode, 
                                                                        country, 
                                                                        dataAreaId  ).SalesDistrictId;
}

/// <summary>
///    AVA <c>modifiedField</c> method.
/// </summary>
/// <param name="_fieldId">
///    <c>FieldId</c> as type
/// </param>
public void modifiedField(FieldId _fieldId)
{
    //LogisticsPostalAddress          logisticsPostalAddress;
    LogisticsAddressZipCode         logisticsAddressZipCode;
    switch(_fieldId)
    {
        case fieldNum(KCS_KBVBuildingProjectTable, AddressCountryRegionId):
            this.setSalesDistrict();
            break;
        case fieldNum(KCS_KBVBuildingProjectTable, AddressZipCodeId):
            select firstonly logisticsAddressZipCode
                order by ZipCode ASC
            //    where (logisticsPostalAddress.City               == this.AddressCity || this.AddressCity == '')
            where  logisticsAddressZipCode.ZipCode             == this.AddressZipCodeId
                   && logisticsAddressZipCode.CountryRegionId     == this.AddressCountryRegionId
                   && ((logisticsAddressZipCode.City == this.AddressCity && this.AddressCity != '') || this.AddressCity == '');

            if (!logisticsAddressZipCode.RecId)
            {
                select firstonly logisticsAddressZipCode
                order by ZipCode ASC
            //    where (logisticsPostalAddress.City               == this.AddressCity || this.AddressCity == '')
                where  logisticsAddressZipCode.ZipCode             == this.AddressZipCodeId
                   && logisticsAddressZipCode.CountryRegionId     == this.AddressCountryRegionId;

            }

            if (logisticsAddressZipCode.City)
            {
                this.AddressCity = logisticsAddressZipCode.City;
                this.setSalesDistrict();
            }
            break;
        case fieldNum(KCS_KBVBuildingProjectTable,AddressCity) :

            LogisticsAddressCity            checkAddressCity;
            boolean setZipCode = false;
            if (this.orig().addressCity && this.orig().addressCity != this.AddressCity)
            {
                setZipCode = true;
            }
            else if (!this.AddressZipCodeId)
            {
                setZipCode = true;                
            }

            if (setZipCode)
            {
                this.AddressZipCodeId = '';

                select count(RecId) from checkAddressCity
                where checkAddressCity.Name == this.AddressCity
                && checkAddressCity.CountryRegionId == this.AddressCountryRegionId;

                if (checkAddressCity.RecId == any2Int64(1))
                {
                    select firstonly logisticsAddressZipCode
                order by ZipCode ASC
                where logisticsAddressZipCode.City               == this.AddressCity
                   && logisticsAddressZipCode.ZipCode            != ''
                   && logisticsAddressZipCode.CountryRegionId    != ''

                   && logisticsAddressZipCode.CountryRegionId    == this.AddressCountryRegionId;

                    if (logisticsAddressZipCode.RecId)
                    {
                        this.AddressZipCodeId       = logisticsAddressZipCode.ZipCode;
                        this.AddressCountryRegionId = logisticsAddressZipCode.CountryRegionId;
                        this.setSalesDistrict();
                    }
                }
            }

            break;

        case fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVTenderFirstPosition) :
            KCS_KBVSearchTable::setFromCommonField(this.KCS_KBVBuildingProjectID,this,_fieldId);
            break;
        default : 
            break;
    }

    super(_fieldId);
}

