/// <summary>
///    AVA <c>updateBPStatus</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectTable">
///    <c>KCS_KBVBuildingProjectTable</c> as type
/// </param>
/// <param name="_showInfo">
///    <c>boolean</c> as type
/// </param>
public server static void updateBPStatus(   KCS_KBVBuildingProjectTable _kcs_KBVBuildingProjectTable, 
                                            boolean                     _showInfo                       = true  )
{
    KCS_KBVBPCompanySpecific    kcs_KBVBPCompanySpecific;

    KCS_KBVStatus               kbvStatus = KCS_KBVStatus::Project;
    container                   kbvCompanies;
    int                         nInquired, nLocked, nWon, nLost, nDeclined, nAnswered, nPartialWon, nCompanySpecific;

    nInquired           = 0;
    nLocked             = 0;
    nWon                = 0;
    nLost               = 0;
    nDeclined           = 0;
    nAnswered           = 0;
    nPartialWon         = 0;
    nCompanySpecific    = 0;

    if (!_kcs_KBVBuildingProjectTable)
    {
        return;
    }

    kbvCompanies = AVAKBVBuildingProjectHelper::getAllBPCompanies();

    while select crosscompany : kbvCompanies KCS_KBVBuildingProjectID, KCS_KBVStatus, count(recid) 
    from        kcs_KBVBPCompanySpecific
    group by    KCS_KBVStatus
    where       kcs_KBVBPCompanySpecific.KCS_KBVBuildingProjectID == _kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID
    {
        nCompanySpecific += int642int(kcs_KBVBPCompanySpecific.RecId);

        switch(kcs_KBVBPCompanySpecific.KCS_KBVStatus)
        {
            //angefragt
            case KCS_KBVStatus::Inquired:
                nInquired = int642int(kcs_KBVBPCompanySpecific.RecId);
                break;
            //gesperrt
            case KCS_KBVStatus::Locked:
                nLocked = int642int(kcs_KBVBPCompanySpecific.RecId);
                break;
            //gewonnen
            case KCS_KBVStatus::Won:
                nWon = int642int(kcs_KBVBPCompanySpecific.RecId);
                break;
            //verloren
            case KCS_KBVStatus::Lost:
                nLost = int642int(kcs_KBVBPCompanySpecific.RecId);
                break;
            //abgelehnt
            case KCS_KBVStatus::Declined:
                nDeclined = int642int(kcs_KBVBPCompanySpecific.RecId);
                break;
            //beantwortet
            case KCS_KBVStatus::Answered:
                nAnswered = int642int(kcs_KBVBPCompanySpecific.RecId);
                break;
            //teilweise gewonnen
            case KCS_KBVStatus::PartialWon:
                nPartialWon = int642int(kcs_KBVBPCompanySpecific.RecId);
                break;
        }
    }

    //auswerten
    if(nCompanySpecific)
    {
        //alle Datensätze sind angefragt
        if(     nInquired
            &&  nInquired       == nCompanySpecific )
        {
            kbvStatus = KCS_KBVStatus::Inquired;
        }
        //alle Datensätze sind angefragt
        else if(    nLocked
                &&  nLocked     == nCompanySpecific )
        {
            kbvStatus = KCS_KBVStatus::Locked;
        }
        //alle Datensätze sind gewonnen
        else if(    nWon 
                &&  nWon        == nCompanySpecific )
        {
            kbvStatus = KCS_KBVStatus::Won;
        }
        //alle Datensätze sind verloren
        else if(    nLost
                &&  nLost       == nCompanySpecific )
        {
            kbvStatus = KCS_KBVStatus::Lost;
        }
        //alle Datensätze sind abgelehnt
        else if(    nDeclined
                &&  nDeclined   == nCompanySpecific )
        {
            kbvStatus = KCS_KBVStatus::Declined;
        }
        //alle Datensätze sind beantwortet
        else if(    nAnswered
                &&  nAnswered   == nCompanySpecific )
        {
            kbvStatus = KCS_KBVStatus::Answered;
        }
        //alle Datensätze sind teilweise gewonnen
        else if(    nPartialWon
                &&  nPartialWon == nCompanySpecific )
        {
            kbvStatus = KCS_KBVStatus::PartialWon;
        }
        else  // not all of the same but special constellations
        {
            //alle Datensätze sind verloren und abgelehnt
            if(     nLost
                &&  nDeclined
                &&  ((nLost + nDeclined)    == nCompanySpecific)    )
            {
                kbvStatus = KCS_KBVStatus::Lost;
            }
            //einer verloren oder beantwortet
            if(     nLost
                ||  nAnswered   )
            {
                kbvStatus = kCS_KBVStatus::Answered;
            }
            //nur ändern wenn Status des BV nicht schon folgende beträgt
            if(     _kcs_KBVBuildingProjectTable.KCS_KBVStatus != KCS_KBVStatus::Locked
                &&  _kcs_KBVBuildingProjectTable.KCS_KBVStatus != KCS_KBVStatus::Won
                &&  _kcs_KBVBuildingProjectTable.KCS_KBVStatus != KCS_KBVStatus::Lost
                &&  _kcs_KBVBuildingProjectTable.KCS_KBVStatus != KCS_KBVStatus::Declined   )
            {
                //mind. 1 Datensatz ist angefragt
                if(nInquired)
                {
                    kbvStatus = KCS_KBVStatus::Inquired;
                }
                //mind. ein Datensatz ist beantwortet und mind. einer abgelehnt
                if(     nAnswered
                    &&  nDeclined   )
                {
                    kbvStatus = KCS_KBVStatus::Answered;
                }
            }
            //mind. ein Datensatz gewonnen oder teilweise gewonnen
            if(     nWon 
                ||  nPartialWon )
            {
                kbvStatus = KCS_KBVStatus::PartialWon;
            }
            //alle Datensätze sind angefragt und beantwortet
            if(     nInquired
                &&  nAnswered
                &&  ((nInquired + nAnswered)    == nCompanySpecific)    )
            {
                kbvStatus = KCS_KBVStatus::Inquired;
            }
        }

    /* original version          
        //mind. 1 Datensatz ist angefragt
        //nur ändern wenn Status des BV nicht schon folgende beträgt
        if(     nInquired 
            &&  _kcs_KBVBuildingProjectTable.KCS_KBVStatus  != KCS_KBVStatus::Locked
            &&  _kcs_KBVBuildingProjectTable.KCS_KBVStatus  != KCS_KBVStatus::Won
            &&  _kcs_KBVBuildingProjectTable.KCS_KBVStatus  != KCS_KBVStatus::Lost
            &&  _kcs_KBVBuildingProjectTable.KCS_KBVStatus  != KCS_KBVStatus::Declined   )
        {
            kbvStatus = KCS_KBVStatus::Inquired;
        }

        //einer verloren oder beantwortet
        if(     nLost
            ||  nAnswered   )
        {
            kbvStatus = kCS_KBVStatus::Answered;
        }

        //alle Datensätze sind abgelehnt
        if(     nDeclined
            &&  nDeclined == nCompanySpecific)
        {
            kbvStatus = KCS_KBVStatus::Declined;
        }

        //alle Datensätze sind verloren
        if(     nLost
            &&  nLost == nCompanySpecific   )
        {
            kbvStatus = KCS_KBVStatus::Lost;
        }

        //alle Datensätze sind verloren und abgelehnt
        if(     nLost
            &&  nDeclined
            &&  ((nLost + nDeclined)== nCompanySpecific)    )
        {
            kbvStatus = KCS_KBVStatus::Lost;
        }

        //alle Datensätze sind teilweise gewonnen
        if(     nPartialWon
            &&  nPartialWon == nCompanySpecific )
        {
            kbvStatus = KCS_KBVStatus::PartialWon;
        }

        //alle Datensätze sind beantwortet
        if(     nAnswered
            &&  nAnswered == nCompanySpecific   )
        {
            kbvStatus = KCS_KBVStatus::Answered;
        }

        //mind. ein Datensatz ist beantwortet und einer abgelehnt
        //nur ändern wenn Status des BV nicht schon folgende beträgt
        if(     nAnswered
            &&  nDeclined
            &&  _kcs_KBVBuildingProjectTable.KCS_KBVStatus != KCS_KBVStatus::Locked
            &&  _kcs_KBVBuildingProjectTable.KCS_KBVStatus != KCS_KBVStatus::Won
            &&  _kcs_KBVBuildingProjectTable.KCS_KBVStatus != KCS_KBVStatus::Lost
            &&  _kcs_KBVBuildingProjectTable.KCS_KBVStatus != KCS_KBVStatus::Declined   )
        {
            kbvStatus = KCS_KBVStatus::Answered;
        }

        //mind. ein Datensatz gewonnen oder teilweise gewonnen
        if(nWon || nPartialWon)
        {
            kbvStatus = KCS_KBVStatus::PartialWon;
        }

        //alle Datensätze sind gewonnen
        if(nWon && nWon == nCompanySpecific)
        {
            kbvStatus = KCS_KBVStatus::Won;
        }
    */
    }

    //speichern
    if (_kcs_KBVBuildingProjectTable.KCS_KBVStatus != kbvStatus)
    {
        if (_showInfo)
        {
            info(strfmt("@NDX:NXABPStatusChangedFromTo", _kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
            _kcs_KBVBuildingProjectTable.KCS_KBVStatus, KBVStatus));
        }

        _kcs_KBVBuildingProjectTable.selectForUpdate(true);
        _kcs_KBVBuildingProjectTable.KCS_KBVStatus = kbvStatus;
        _kcs_KBVBuildingProjectTable.write();
    }
}

/// <summary>
///    AVA <c>checkLimit</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean checkLimit()
{
    KCS_KBVParameters               kcs_KBVParameters;
    KCS_KBVPotentialSalesVolumeTbl  kcs_KBVPotentialSalesVolumeTbl;

    kcs_KBVParameters = kcs_KBVParameters::find();
    if (!kcs_KBVParameters.RecId)
    {
        return false;
    }

    if (this.smmQuotationProbabilityId >= kcs_KBVParameters.KCS_KBVInfoPropLimit)
    {
        return true;
    }

    select firstOnly1 kcs_KBVPotentialSalesVolumeTbl
    where   kcs_KBVPotentialSalesVolumeTbl.KCS_KBVBuildingProjectID == this.KCS_KBVBuildingProjectID;

    //if (kcs_KBVPotentialSalesVolumeTbl.KCS_KBVPotentialSalesVolume > kcs_KBVParameters.KCS_KBVInfoRevLimit)
    if (kcs_KBVPotentialSalesVolumeTbl.KCS_KBVPotentialSalesVolume > AVAKBVHelperClass::kbvInfoRevLimitDataAreaId())
    {
        return true;
    }



    return false;
}

