/// </summary>
/// <returns>
///     <c>DirPartyName</c> as type
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
public display DirPartyName displayHighestPrioDirPartyName()
{
    DirPartyName    retVal;
    KCS_KBVRelationsToBV     locKCS_KBVRelationsToBV;

    locKCS_KBVRelationsToBV = AVAKBVHelperClass::getHighestRelation(this.KCS_KBVBuildingProjectID);
    if(locKCS_KBVRelationsToBV.RecId)
    {
        retVal = DirPartyTable::findRec(locKCS_KBVRelationsToBV.DirPartyId).Name;
    }

    return retVal;
}

/// <summary>
/// Simple building project id lookup
/// </summary>
/// <param name = "_lookupCtrl">FormStringControl</param>
public static void lookup(FormStringControl _lookupCtrl)
{
    Query                   query = new Query();
    QueryBuildDataSource    queryBuildDataSource = query.addDataSource(tableNum(KCS_KBVBuildingProjectTable));

    queryBuildDataSource.addSelectionField(fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID));
    queryBuildDataSource.addSortField(fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID), SortOrder::Ascending);

    SysTableLookup  sysTableLookup  = SysTableLookup::newParameters(tableNum(KCS_KBVBuildingProjectTable), _lookupCtrl);

    sysTableLookup.addLookupfield(fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID));
    sysTableLookup.addLookupfield(fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVSubject));

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

