/// <summary>
///     AVA <c>avaGetResponsibleFieldWorker</c> method.
///     AVA - Schneider 28.05.2024
/// </summary>
/// <param name="_planned">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>HCMWorker</c> as return value
/// </returns>
public HCMWorker avaGetResponsibleFieldWorker(boolean _planned = false)
{
    HCMWorker                       retVal;

    smmResponsibilityId             locsmmResponsibilityId;
    KCS_KBVResponsibilitiesTable    locKCS_KBVResponsibilitiesTable;
    smmWorker                       locsmmWorker;

    locsmmResponsibilityId = smmResponsibilityGroup::avaResponsibleFieldWorkerResponsibilityId(); // ADM
    if(locsmmResponsibilityId)
    {
        locKCS_KBVResponsibilitiesTable = KCS_KBVResponsibilitiesTable::find(this.KCS_KBVBuildingProjectID, locsmmResponsibilityId);

        if(locKCS_KBVResponsibilitiesTable.RecId)
        {
            if(_planned)
            {
                if(locKCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate == dateNull())
                {
                    locsmmWorker = locKCS_KBVResponsibilitiesTable.smmWorker;
                }
            }
            else
            {
                locsmmWorker = locKCS_KBVResponsibilitiesTable.smmWorker;
            }
        }
    }

    if(locsmmWorker)
    {
        retVal = HcmWorker::find(locsmmWorker);
    }

    return retVal;
}

