/// <summary>
/// N.Freidenberger 10.14.2024
/// </summary>
/// <param name = "_buildingProjectId">_buildingProjectId</param>
/// <param name = "_dataAreaId">_dataAreaId</param>
/// <returns>int</returns>
public static int64 numberOfRequestCrossCompany(KCS_KBVBuildingProjectID        _buildingProjectId, DataAreaId  _dataAreaId)
{
    KCS_KBVRequestTable         requestTable;
    int64                       countReq;

    changecompany(_dataAreaId)
    {
        select crosscompany count(RecId)  from requestTable
            where requestTable.KCS_KBVBuildingProjectID == _buildingProjectId;

        countReq = requestTable.RecId;
    }

    return countReq;

}
